INSERT INTO public.references (source_name, source_type, source_url, notes) VALUES
('WHO Model List of Essential Medicines','Regulatory / WHO','https://www.who.int/publications/i/item/WHO-MHP-HPS-EML-2023.02','Essential medicines listing'),
('National List of Essential Medicines (NLEM), India','Government / Regulatory','https://cdsco.gov.in/','Indian essential medicines list'),
('KD Tripathi, Essentials of Medical Pharmacology','Textbook',NULL,'Standard Indian pharmacology textbook'),
('Goodman & Gilman''s The Pharmacological Basis of Therapeutics','Textbook',NULL,'Reference pharmacology text'),
('DailyMed / US FDA Prescribing Information','Regulatory','https://dailymed.nlm.nih.gov/','Product labelling'),
('British National Formulary (BNF)','Formulary','https://bnf.nice.org.uk/','Clinical formulary');
INSERT INTO public.drug_classes (slug,name,class_type,simple_explanation,hindi_explanation,clinical_definition,common_uses) VALUES
('analgesics','Analgesics','therapeutic','Medicines that reduce or relieve pain.','Dard ko kam ya relieve karne wali dawa ko analgesic kehte hain.','Agents that relieve pain without causing loss of consciousness.',ARRAY['Pain','Fever (some agents)']),
('antimicrobials','Antimicrobials','therapeutic','Medicines that kill or stop germs.','Infection paida karne wale germs ko maarne ya rokne wali dawa.','Agents active against bacteria, fungi, viruses or parasites.',ARRAY['Bacterial infection','Fungal infection','Viral infection']),
('gastrointestinal','Gastrointestinal Agents','therapeutic','Medicines for stomach and gut problems.','Pet, acidity, ulti aur digestion se judi dawaiyan.','Agents acting on the gastrointestinal tract.',ARRAY['Acidity','GERD','Nausea','Ulcer']),
('cardiovascular','Cardiovascular Agents','therapeutic','Medicines for heart and blood pressure.','Dil aur blood pressure se judi dawaiyan.','Agents acting on the heart, vessels and circulation.',ARRAY['Hypertension','Angina','Heart failure']),
('respiratory','Respiratory Agents','therapeutic','Medicines for breathing problems.','Saans aur asthma se judi dawaiyan.','Agents acting on the airways and respiratory system.',ARRAY['Asthma','COPD','Cough']),
('endocrine','Endocrine & Metabolic Agents','therapeutic','Medicines for hormones, diabetes and thyroid.','Hormone, diabetes aur thyroid se judi dawaiyan.','Agents modifying endocrine and metabolic function.',ARRAY['Diabetes','Hypothyroidism']),
('allergy-immunology','Allergy & Immunology','therapeutic','Medicines for allergy and immune reactions.','Allergy aur immune reaction ki dawaiyan.','Agents modifying allergic and immune responses.',ARRAY['Allergic rhinitis','Urticaria']),
('haematology','Blood & Haematology','therapeutic','Medicines affecting blood clotting.','Khoon jamne ki process par asar karne wali dawaiyan.','Agents modifying haemostasis and blood constituents.',ARRAY['Thrombosis prevention']),
('lipid-lowering','Lipid-Lowering Agents','therapeutic','Medicines that lower cholesterol.','Cholesterol kam karne wali dawaiyan.','Agents reducing plasma lipid levels.',ARRAY['Dyslipidaemia','Cardiovascular risk reduction']);
INSERT INTO public.drug_classes (slug,name,class_type,parent_id,key_suffix,simple_explanation,hindi_explanation,clinical_definition,mechanism,common_uses,key_adverse_effects,contraindications,advantages,disadvantages) VALUES
('non-opioid-analgesics','Non-Opioid Analgesics','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='analgesics'),NULL,'Pain relievers that are not opioids.','Wo painkillers jo opioid nahi hote.','Analgesic agents acting without opioid receptor agonism.','Central COX inhibition and other central mechanisms (paracetamol).',ARRAY['Mild to moderate pain','Fever'],ARRAY['Hepatotoxicity in overdose (paracetamol)'],ARRAY['Severe hepatic impairment (caution)'],ARRAY['Widely available','Generally well tolerated at therapeutic doses'],ARRAY['Limited anti-inflammatory effect (paracetamol)']),
('nsaids','NSAIDs','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='analgesics'),'-profen / -fenac','Pain and inflammation medicines.','Dard aur soojan dono kam karne wali dawaiyan.','Non-steroidal anti-inflammatory drugs inhibiting cyclo-oxygenase enzymes.','Inhibit COX-1/COX-2, reducing prostaglandin synthesis.',ARRAY['Pain','Inflammation','Fever','Dysmenorrhoea'],ARRAY['Gastric irritation','Peptic ulcer','Renal impairment','Increased bleeding risk'],ARRAY['Active peptic ulcer','Severe renal impairment','NSAID hypersensitivity'],ARRAY['Anti-inflammatory in addition to analgesic effect'],ARRAY['Gastrointestinal and renal adverse effects with prolonged use']),
('beta-lactams','Beta-Lactam Antibiotics','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='antimicrobials'),'-cillin / cef-','Antibiotics that break bacterial cell walls.','Bacteria ki deewar todne wale antibiotics.','Antibiotics containing a beta-lactam ring that inhibit cell wall synthesis.','Bind penicillin-binding proteins, inhibiting peptidoglycan cross-linking.',ARRAY['Respiratory infection','Urinary infection','Skin infection'],ARRAY['Rash','Diarrhoea','Hypersensitivity reactions'],ARRAY['Known beta-lactam anaphylaxis'],ARRAY['Bactericidal','Broad clinical experience'],ARRAY['Resistance via beta-lactamases','Allergy risk']),
('macrolides','Macrolides','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='antimicrobials'),'-thromycin','Antibiotics that stop bacteria making proteins.','Bacteria ka protein banna rokne wale antibiotics.','Macrocyclic lactone antibiotics binding the 50S ribosomal subunit.','Bind 50S ribosomal subunit and inhibit bacterial protein synthesis.',ARRAY['Atypical pneumonia','Pharyngitis in penicillin allergy'],ARRAY['Nausea','QT prolongation'],ARRAY['Macrolide hypersensitivity'],ARRAY['Useful in penicillin allergy','Good tissue penetration'],ARRAY['Drug interactions via CYP3A4 (some agents)']),
('tetracyclines','Tetracyclines','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='antimicrobials'),'-cycline','Broad antibiotics that stop bacterial protein production.','Broad-spectrum antibiotics jo bacteria ka protein banna rokte hain.','Antibiotics binding the 30S ribosomal subunit.','Bind 30S subunit, blocking aminoacyl-tRNA attachment.',ARRAY['Acne','Atypical infections','Rickettsial infection'],ARRAY['Photosensitivity','Oesophageal irritation','Tooth discolouration in children'],ARRAY['Pregnancy','Children under 8 years (generally)'],ARRAY['Broad spectrum','Oral administration'],ARRAY['Not suitable in pregnancy or young children']),
('nitroimidazoles','Nitroimidazoles','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='antimicrobials'),'-nidazole','Medicines for anaerobic bacteria and some parasites.','Anaerobic bacteria aur kuch parasites ke liye dawa.','Agents activated in anaerobic organisms causing DNA damage.','Reduced nitro group forms reactive intermediates damaging microbial DNA.',ARRAY['Amoebiasis','Giardiasis','Anaerobic infection'],ARRAY['Metallic taste','Nausea','Disulfiram-like reaction with alcohol'],ARRAY['Known hypersensitivity'],ARRAY['Effective against anaerobes and protozoa'],ARRAY['Alcohol interaction','Taste disturbance']),
('ppis','Proton Pump Inhibitors (PPI)','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='gastrointestinal'),'-prazole','Strong acid-reducing medicines.','Pet ka acid strongly kam karne wali dawaiyan.','Irreversible inhibitors of the gastric H+/K+-ATPase.','Irreversibly inhibit the gastric proton pump in parietal cells.',ARRAY['GERD','Peptic ulcer','H. pylori regimens'],ARRAY['Headache','Diarrhoea','Hypomagnesaemia with long-term use'],ARRAY['Hypersensitivity to PPIs'],ARRAY['Potent and durable acid suppression'],ARRAY['Long-term use associated risks']),
('antiemetics','Antiemetics','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='gastrointestinal'),'-setron','Medicines that stop vomiting.','Ulti rokne wali dawaiyan.','Agents preventing or relieving nausea and vomiting.','5-HT3 receptor antagonism (setrons) and other pathways.',ARRAY['Chemotherapy-induced vomiting','Post-operative vomiting'],ARRAY['Headache','Constipation','QT prolongation'],ARRAY['Concomitant apomorphine (ondansetron)'],ARRAY['Effective and well tolerated'],ARRAY['QT effects at higher doses']),
('antihistamines','Antihistamines (H1)','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='allergy-immunology'),'-tadine / -zine','Allergy medicines.','Allergy ki dawaiyan.','H1 receptor inverse agonists/antagonists.','Block histamine H1 receptors, reducing allergic response.',ARRAY['Allergic rhinitis','Urticaria','Itching'],ARRAY['Drowsiness (variable)','Dry mouth'],ARRAY['Hypersensitivity'],ARRAY['Second-generation agents are less sedating'],ARRAY['Sedation with first-generation agents']),
('bronchodilators','Beta-2 Agonist Bronchodilators','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='respiratory'),'-terol','Medicines that open airways.','Saans ki naliyon ko kholne wali dawaiyan.','Selective beta-2 adrenoceptor agonists relaxing bronchial smooth muscle.','Stimulate beta-2 receptors, increasing cAMP and relaxing airway smooth muscle.',ARRAY['Asthma','COPD'],ARRAY['Tremor','Palpitations','Hypokalaemia'],ARRAY['Hypersensitivity'],ARRAY['Rapid relief of bronchospasm (short-acting)'],ARRAY['Not anti-inflammatory; overuse signals poor control']),
('biguanides','Biguanides','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='endocrine'),NULL,'First-line diabetes tablets.','Diabetes ki first-line tablet.','Antihyperglycaemic agents reducing hepatic glucose output.','Reduce hepatic gluconeogenesis and improve insulin sensitivity (AMPK-related).',ARRAY['Type 2 diabetes mellitus'],ARRAY['GI upset','Vitamin B12 deficiency','Lactic acidosis (rare)'],ARRAY['Severe renal impairment','Acute metabolic acidosis'],ARRAY['Weight neutral','No intrinsic hypoglycaemia'],ARRAY['GI intolerance','Renal restrictions']),
('sulfonylureas','Sulfonylureas','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='endocrine'),'gli-','Diabetes tablets that push insulin release.','Insulin release badhane wali diabetes tablets.','Agents closing pancreatic beta-cell K-ATP channels.','Close K-ATP channels, depolarising beta cells and releasing insulin.',ARRAY['Type 2 diabetes mellitus'],ARRAY['Hypoglycaemia','Weight gain'],ARRAY['Type 1 diabetes','Severe hepatic/renal impairment'],ARRAY['Effective glucose lowering','Low cost'],ARRAY['Hypoglycaemia risk']),
('ccb','Calcium Channel Blockers','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='cardiovascular'),'-dipine','Blood pressure medicines that relax vessels.','Blood vessels ko relax karke BP kam karne wali dawa.','Agents blocking L-type calcium channels.','Block L-type calcium channels causing vasodilation.',ARRAY['Hypertension','Angina'],ARRAY['Ankle oedema','Flushing','Headache'],ARRAY['Severe aortic stenosis (caution)'],ARRAY['Effective in Indian and elderly populations','Once-daily dosing'],ARRAY['Peripheral oedema']),
('arbs','Angiotensin II Receptor Blockers (ARB)','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='cardiovascular'),'-sartan','BP medicines that block a vessel-tightening hormone.','Blood vessel tight karne wale hormone ko block karne wali dawa.','Antagonists of the angiotensin II type 1 receptor.','Block AT1 receptors, preventing angiotensin II mediated vasoconstriction.',ARRAY['Hypertension','Diabetic nephropathy','Heart failure'],ARRAY['Hyperkalaemia','Dizziness','Renal function changes'],ARRAY['Pregnancy','Bilateral renal artery stenosis'],ARRAY['Well tolerated','No cough unlike ACE inhibitors'],ARRAY['Contraindicated in pregnancy']),
('ace-inhibitors','ACE Inhibitors','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='cardiovascular'),'-pril','BP medicines that block an enzyme.','Ek enzyme ko block karke BP kam karne wali dawa.','Inhibitors of angiotensin-converting enzyme.','Inhibit ACE, reducing angiotensin II and aldosterone.',ARRAY['Hypertension','Heart failure','Diabetic nephropathy'],ARRAY['Dry cough','Hyperkalaemia','Angioedema (rare)'],ARRAY['Pregnancy','History of angioedema'],ARRAY['Strong outcome evidence'],ARRAY['Dry cough']),
('loop-diuretics','Loop Diuretics','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='cardiovascular'),NULL,'Strong water-removing medicines.','Sharir se extra paani nikalne wali strong dawa.','Inhibitors of the Na-K-2Cl transporter in the loop of Henle.','Inhibit NKCC2 in the thick ascending limb, causing marked diuresis.',ARRAY['Oedema','Heart failure'],ARRAY['Hypokalaemia','Dehydration','Ototoxicity at high doses'],ARRAY['Anuria','Severe electrolyte depletion'],ARRAY['Rapid and potent diuresis'],ARRAY['Electrolyte disturbance']),
('statins','Statins','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='lipid-lowering'),'-statin','Cholesterol-lowering medicines.','Cholesterol kam karne wali dawaiyan.','HMG-CoA reductase inhibitors.','Inhibit HMG-CoA reductase, upregulating hepatic LDL receptors.',ARRAY['Dyslipidaemia','Cardiovascular risk reduction'],ARRAY['Myalgia','Raised transaminases'],ARRAY['Active liver disease','Pregnancy'],ARRAY['Strong cardiovascular outcome evidence'],ARRAY['Muscle symptoms in some patients']),
('antiplatelets','Antiplatelet Agents','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='haematology'),'-grel','Medicines that stop platelets sticking together.','Platelets ko chipakne se rokne wali dawa.','Agents inhibiting platelet aggregation.','COX-1 inhibition (aspirin) or P2Y12 receptor blockade (clopidogrel).',ARRAY['Secondary prevention of MI/stroke','Acute coronary syndrome'],ARRAY['Bleeding','Bruising','Dyspepsia'],ARRAY['Active bleeding'],ARRAY['Reduce thrombotic events'],ARRAY['Bleeding risk']),
('thyroid-hormones','Thyroid Hormone Replacement','pharmacological',(SELECT id FROM public.drug_classes WHERE slug='endocrine'),NULL,'Replaces a missing thyroid hormone.','Thyroid hormone ki kami poori karne wali dawa.','Synthetic thyroid hormone replacement therapy.','Provides exogenous T4 converted peripherally to active T3.',ARRAY['Hypothyroidism'],ARRAY['Palpitations and tremor if over-replaced'],ARRAY['Untreated adrenal insufficiency','Thyrotoxicosis'],ARRAY['Once-daily, inexpensive, effective'],ARRAY['Needs monitoring and careful timing']);
INSERT INTO public.suffix_patterns (suffix,meaning,class_hint,examples,note) VALUES
('-pril','Many ACE inhibitors','ACE Inhibitors',ARRAY['Enalapril','Ramipril','Lisinopril'],'Memory aid only; exceptions exist.'),
('-sartan','Angiotensin II receptor blockers','ARB',ARRAY['Losartan','Telmisartan','Valsartan'],'Memory aid only; exceptions exist.'),
('-olol','Many beta blockers','Beta Blockers',ARRAY['Atenolol','Metoprolol','Propranolol'],'Memory aid only; exceptions exist.'),
('-statin','Statins','Statins',ARRAY['Atorvastatin','Rosuvastatin','Simvastatin'],'Memory aid only; exceptions exist.'),
('-prazole','Proton pump inhibitors','PPI',ARRAY['Omeprazole','Pantoprazole','Rabeprazole'],'Memory aid only; exceptions exist.'),
('-cillin','Many penicillin antibiotics','Beta-lactams',ARRAY['Amoxicillin','Ampicillin','Cloxacillin'],'Memory aid only; exceptions exist.'),
('-floxacin','Fluoroquinolones','Fluoroquinolones',ARRAY['Ciprofloxacin','Levofloxacin','Ofloxacin'],'Memory aid only; exceptions exist.'),
('-tidine','H2 receptor antagonists','H2 blockers',ARRAY['Ranitidine','Famotidine'],'Memory aid only; exceptions exist.'),
('-caine','Many local anaesthetics','Local anaesthetics',ARRAY['Lignocaine','Bupivacaine'],'Memory aid only; exceptions exist.'),
('-dipine','Dihydropyridine calcium channel blockers','CCB',ARRAY['Amlodipine','Nifedipine'],'Memory aid only; exceptions exist.'),
('-setron','5-HT3 antagonist antiemetics','Antiemetics',ARRAY['Ondansetron','Granisetron'],'Memory aid only; exceptions exist.'),
('-terol','Beta-2 agonist bronchodilators','Bronchodilators',ARRAY['Salbutamol (albuterol)','Formoterol'],'Memory aid only; exceptions exist.'),
('-thromycin','Macrolide antibiotics','Macrolides',ARRAY['Azithromycin','Clarithromycin'],'Memory aid only; exceptions exist.'),
('-cycline','Tetracycline antibiotics','Tetracyclines',ARRAY['Doxycycline','Minocycline'],'Memory aid only; exceptions exist.');
INSERT INTO public.medical_terms (slug,term,category,definition,simple_definition,hindi_explanation,hinglish_explanation,pronunciation_en) VALUES
('analgesic','Analgesic','Drug class','A medicine used to relieve pain.','A pain-relief medicine.','Dard ko kam ya relieve karne wali dawa ko analgesic kehte hain.','Pain kam karne wali medicine.','an-al-JEE-zik'),
('antipyretic','Antipyretic','Drug class','A medicine that reduces fever.','Fever-reducing medicine.','Bukhar kam karne wali dawa.','Fever/bukhar kam karne wali medicine.','an-tee-py-RET-ik'),
('nsaid','NSAID','Drug class','Non-steroidal anti-inflammatory drug that reduces pain, fever and inflammation.','Pain plus swelling medicine.','Dard, bukhar aur soojan kam karne wali non-steroid dawa.','Pain + swelling dono kam karti hai.','EN-said'),
('antibiotic','Antibiotic','Drug class','A medicine that kills or inhibits bacteria.','Medicine against bacteria.','Bacteria ko maarne ya rokne wali dawa.','Bacteria wali infection ki medicine.','an-ti-by-OT-ik'),
('antiviral','Antiviral','Drug class','A medicine active against viruses.','Medicine against viruses.','Virus ke khilaf kaam karne wali dawa.','Virus ke liye medicine.','an-ti-VY-ral'),
('antifungal','Antifungal','Drug class','A medicine active against fungal infections.','Medicine against fungus.','Fungal infection ki dawa.','Fungus ke liye medicine.','an-ti-FUN-gal'),
('antihistamine','Antihistamine','Drug class','A medicine that blocks histamine receptors, used in allergy.','Allergy medicine.','Allergy me use hone wali dawa jo histamine ko block karti hai.','Allergy block karne wali medicine.','an-ti-HISS-ta-meen'),
('antacid','Antacid','Drug class','An agent that neutralises gastric acid.','Neutralises stomach acid.','Pet ke acid ko neutralise karne wali dawa.','Acidity turant kam karti hai.','ant-ASS-id'),
('ppi','PPI','Drug class','Proton pump inhibitor; strongly reduces gastric acid secretion.','Strong acid-reducing medicine.','Pet ka acid banna strongly kam karne wali dawa.','Acid production hi kam kar deti hai.','P-P-I'),
('diuretic','Diuretic','Drug class','A medicine that increases urine output.','Medicine that increases urine.','Peshaab zyada karwa kar extra paani nikalne wali dawa.','Extra paani nikalti hai.','dy-yoo-RET-ik'),
('beta-blocker','Beta Blocker','Drug class','A medicine blocking beta-adrenergic receptors.','Slows the heart and lowers BP.','Heart rate aur BP kam karne wali dawa.','Heart ko slow karti hai.','BAY-ta BLOK-er'),
('ace-inhibitor','ACE Inhibitor','Drug class','A medicine inhibiting angiotensin-converting enzyme.','BP medicine blocking an enzyme.','ACE enzyme ko block karke BP kam karti hai.','BP ki medicine, kabhi khansi karti hai.','A-C-E in-HIB-i-tor'),
('arb','ARB','Drug class','Angiotensin II receptor blocker.','BP medicine blocking a receptor.','Angiotensin receptor ko block karke BP kam karti hai.','ACE jaisi, par cough nahi.','A-R-B'),
('ccb','Calcium Channel Blocker','Drug class','A medicine blocking L-type calcium channels.','Relaxes blood vessels.','Blood vessels relax karke BP kam karti hai.','Vessels ko relax karti hai.','KAL-see-um CHAN-el BLOK-er'),
('anticoagulant','Anticoagulant','Drug class','A medicine that reduces blood clot formation.','Thins the blood.','Khoon jamne ki process ko dheema karne wali dawa.','Blood clot rokti hai.','an-ty-ko-AG-yoo-lant'),
('antiplatelet','Antiplatelet','Drug class','A medicine preventing platelet aggregation.','Stops platelets clumping.','Platelets ko aapas me chipakne se rokti hai.','Clot banne se rokti hai.','an-ty-PLATE-let'),
('statin','Statin','Drug class','An HMG-CoA reductase inhibitor that lowers LDL cholesterol.','Cholesterol-lowering medicine.','Cholesterol kam karne wali dawa.','LDL cholesterol kam karti hai.','STAT-in'),
('corticosteroid','Corticosteroid','Drug class','A steroid hormone analogue with anti-inflammatory action.','Strong anti-inflammatory medicine.','Soojan ko strongly kam karne wali steroid dawa.','Inflammation kam karti hai.','kor-ti-ko-STER-oyd'),
('bronchodilator','Bronchodilator','Drug class','A medicine widening the airways.','Opens the airways.','Saans ki naliyon ko chaudi karne wali dawa.','Saans khol deti hai.','brong-ko-DY-lay-tor'),
('mucolytic','Mucolytic','Drug class','A medicine that thins mucus.','Loosens thick mucus.','Gaadhe balgam ko patla karne wali dawa.','Balgam patla karti hai.','myoo-ko-LIT-ik'),
('expectorant','Expectorant','Drug class','An agent aiding the expulsion of airway secretions.','Helps cough out mucus.','Balgam bahar nikalne me madad karne wali dawa.','Balgam nikalne me help karti hai.','ek-SPEK-tor-ant'),
('antitussive','Antitussive','Drug class','A medicine that suppresses cough.','Stops dry cough.','Sookhi khansi ko dabane wali dawa.','Dry cough rokti hai.','an-ti-TUSS-iv'),
('sedative','Sedative','Drug class','An agent producing calming effects.','Calming medicine.','Shant karne wali dawa.','Calm karti hai.','SED-a-tiv'),
('hypnotic','Hypnotic','Drug class','An agent that induces sleep.','Sleep-inducing medicine.','Neend laane wali dawa.','Neend laati hai.','hip-NOT-ik'),
('antidepressant','Antidepressant','Drug class','A medicine used in depressive disorders.','Medicine for depression.','Depression ke ilaj me use hone wali dawa.','Mood disorder ki medicine.','an-ty-dee-PRESS-ant'),
('antipsychotic','Antipsychotic','Drug class','A medicine used in psychotic disorders.','Medicine for psychosis.','Psychosis ke ilaj me use hone wali dawa.','Psychosis ki medicine.','an-ty-sy-KOT-ik'),
('antiepileptic','Antiepileptic','Drug class','A medicine used to prevent seizures.','Seizure-preventing medicine.','Mirgi ke daure rokne wali dawa.','Fits rokne ki medicine.','an-ty-ep-i-LEP-tik'),
('antiemetic','Antiemetic','Drug class','A medicine preventing nausea and vomiting.','Stops vomiting.','Ulti rokne wali dawa.','Vomiting rokti hai.','an-ty-ee-MET-ik'),
('laxative','Laxative','Drug class','An agent promoting bowel evacuation.','Relieves constipation.','Kabz door karne wali dawa.','Constipation ki medicine.','LAX-a-tiv'),
('antiseptic','Antiseptic','Term','An agent applied to living tissue to reduce infection risk.','Germ killer for skin.','Skin par lagane wala germ-killer.','Skin ke liye germ killer.','an-ti-SEP-tik'),
('disinfectant','Disinfectant','Term','An agent applied to non-living surfaces to destroy microbes.','Germ killer for surfaces.','Surfaces ke liye germ-killer.','Surface ka germ killer.','dis-in-FEK-tant'),
('agonist','Agonist','Pharmacodynamics','A substance that binds a receptor and produces a response.','Activates a receptor.','Receptor se judkar usko activate karne wala.','Receptor ko ON karta hai.','AG-o-nist'),
('antagonist','Antagonist','Pharmacodynamics','A substance that binds a receptor and blocks a response.','Blocks a receptor.','Receptor ko block karne wala.','Receptor ko OFF karta hai.','an-TAG-o-nist'),
('receptor','Receptor','Pharmacodynamics','A cellular protein to which a drug binds to produce an effect.','The drug''s docking site.','Wo protein jahan dawa judti hai.','Drug ka lock, drug is the key.','ree-SEP-tor'),
('enzyme-inhibitor','Enzyme Inhibitor','Pharmacodynamics','A substance that reduces the activity of an enzyme.','Slows down an enzyme.','Enzyme ki activity kam karne wala.','Enzyme ko slow karta hai.','EN-zime in-HIB-i-tor'),
('half-life','Half-life','Pharmacokinetics','Time required for plasma drug concentration to fall by half.','Time to drop to half.','Dawa ka level aadha hone me lagne wala samay.','Half hone ka time.','HAF-life'),
('bioavailability','Bioavailability','Pharmacokinetics','Fraction of an administered dose reaching systemic circulation unchanged.','How much actually reaches the blood.','Dawa ka kitna hissa khoon tak pahunchta hai.','Blood tak kitna pahuncha.','by-o-a-vay-la-BIL-i-tee'),
('clearance','Clearance','Pharmacokinetics','Volume of plasma cleared of drug per unit time.','How fast the body removes a drug.','Body kitni tezi se dawa hataati hai.','Removal ki speed.','KLEER-ans'),
('volume-of-distribution','Volume of Distribution','Pharmacokinetics','Apparent volume into which a drug distributes.','How widely a drug spreads in the body.','Dawa body me kitni faili hai.','Kitna spread hua.','VOL-yoom of dis-tri-BYOO-shun'),
('adme','ADME','Pharmacokinetics','Absorption, Distribution, Metabolism and Excretion.','The drug''s journey through the body.','Dawa ka body me safar: absorption, distribution, metabolism, excretion.','Drug ka body me journey.','A-D-M-E'),
('pharmacokinetics','Pharmacokinetics','Concept','What the body does to the drug.','Body''s effect on the drug.','Body dawa ke saath kya karti hai.','Body → drug.','far-ma-ko-ki-NET-iks'),
('pharmacodynamics','Pharmacodynamics','Concept','What the drug does to the body.','Drug''s effect on the body.','Dawa body ke saath kya karti hai.','Drug → body.','far-ma-ko-dy-NAM-iks');
